import statistics

def z_score(current, history):
    """history: past readings (not including current), same units as current."""
    mean = statistics.mean(history)
    stdev = statistics.pstdev(history)
    return (current - mean) / stdev if stdev else 0.0

def geopolitical_risk_index(readings, weights=None):
    """readings: {channel: {'current': x, 'history': [...]}}.
    weights: optional {channel: weight}, defaults to equal weight.
    Returns (composite_z, per_channel_z, band).
    """
    channels = list(readings.keys())
    if weights is None:
        weights = {c: 1 / len(channels) for c in channels}

    per_channel_z = {
        c: z_score(readings[c]['current'], readings[c]['history'])
        for c in channels
    }
    composite_z = sum(per_channel_z[c] * weights[c] for c in channels)

    if composite_z < 0.5:
        band = 'Low'
    elif composite_z < 1.0:
        band = 'Moderate'
    elif composite_z < 2.0:
        band = 'Elevated'
    else:
        band = 'Severe'

    return round(composite_z, 2), per_channel_z, band
